// Des: Failure tests: browser link dies, next run resumes safely
// Flo: kill the socket at a stage > run again on a second connection > count what reached the page
// I/O: sim page > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const chaos = @import("te-fail-main.zig"); const snd = @import("ru-chat-send.zig"); const cf = @import("ru-chat-file.zig"); const fq = @import("ru-flow-queu.zig"); const appr = @import("ru-appr-list.zig"); const flo = @import("st-flow-data.zig"); const rig = @import("te-rigz-main.zig"); const file = @import("st-stor-file.zig"); const mock = @import("te-mock-page.zig"); const T = std.testing;
test "link dies before the send click: the next run sends once" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); const conn = try chaos.second(&rg); defer conn.close(); var dead = chaos.dying(&rg, rig.cfgOf(), .live, "before_click"); try T.expect(std.meta.isError(snd.sendText(&dead, "Mom", "chaos one"))); try T.expectEqual(@as(i64, 0), try chaos.numC(&rg, conn, "Z.st.sent.length")); var again = chaos.onConn(&rg, conn, rig.cfgOf(), .live); try T.expect(try snd.sendText(&again, "Mom", "chaos one") == .sent); try T.expectEqual(@as(i64, 1), try chaos.numC(&rg, conn, "Z.st.sent.length")); try T.expectEqualStrings("Mom|chaos one", try chaos.jsC(&rg, conn, "Z.st.sent[0]")); }
test "link dies right after the send click: the message is there, the next run does not send again" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); const conn = try chaos.second(&rg); defer conn.close(); var dead = chaos.dying(&rg, rig.cfgOf(), .live, "after_click"); try T.expect(std.meta.isError(snd.sendText(&dead, "Mom", "chaos two"))); try T.expectEqual(@as(i64, 1), try chaos.numC(&rg, conn, "Z.st.sent.length")); var again = chaos.onConn(&rg, conn, rig.cfgOf(), .live); try T.expect(try snd.sendText(&again, "Mom", "chaos two") == .sent); try T.expectEqual(@as(i64, 1), try chaos.numC(&rg, conn, "Z.st.sent.length")); try T.expect(try rg.sto.sendBegin("Mom", "chaos two", 1) == .dup); }
test "flow: the link dies in item 1, restart resumes at the pending row, nothing doubles, nothing is lost" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); const alo = rg.aren.allocator(); const fl = try appr.planFlow(&rg.sto, alo, "u", "t", &.{ "send Mom flow chaos", "pin Boss", "send Boss second" }, 1); const conn = try chaos.second(&rg); defer conn.close(); var dead = chaos.dying(&rg, rig.cfgOf(), .live, "after_click"); try T.expect(std.meta.isError(fq.run(&dead, fl, .{}))); try T.expectEqual(@as(i64, 1), try chaos.numC(&rg, conn, "Z.st.sent.length")); const its = try flo.itemsOf(&rg.sto, alo, fl); try T.expectEqualStrings("doing", its[0].state); var again = chaos.onConn(&rg, conn, rig.cfgOf(), .live); const res = try fq.run(&again, fl, .{}); try T.expectEqual(@as(u32, 3), res.done); try T.expectEqual(@as(i64, 2), try chaos.numC(&rg, conn, "Z.st.sent.length")); try T.expectEqualStrings("Boss", try chaos.jsC(&rg, conn, "Z.st.pin[0]")); try T.expectEqualStrings("done", (try flo.flowLatest(&rg.sto, alo)).?.state); }
test "link dies after the file was chosen: the next run waits for the upload and does not upload twice" { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var pbuf: [160]u8 = undefined; const rel = try std.fmt.bufPrint(&pbuf, ".zig-cache/tmp/{s}/outb", .{tmpz.sub_path}); var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); const alo = rg.aren.allocator(); const box = try mock.absPath(alo, T.io, rel); const path = try std.fs.path.join(alo, &.{ box, "chaos.pdf" }); try file.fileAtom(alo, T.io, path, "pdf"); var cfg = rig.cfgOf(); cfg.outb_dirz_path = box; cfg.file_size_maxz = 1000; const conn = try chaos.second(&rg); defer conn.close(); var dead = chaos.dying(&rg, cfg, .live, "after_choose"); try T.expect(std.meta.isError(cf.sendFile(&dead, "Mom", "chaos.pdf"))); var again = chaos.onConn(&rg, conn, cfg, .live); try T.expect(try cf.sendFile(&again, "Mom", "chaos.pdf") == .sent); try T.expectEqual(@as(i64, 1), try chaos.numC(&rg, conn, "Z.st.uploads.length")); }
